package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

var scanner *bufio.Scanner

func init() {
	scanner = bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanLines)
}

func readLine() string {
	scanner.Scan()
	return scanner.Text()
}

func readInt() int {
	line := readLine()
	val, _ := strconv.Atoi(line)
	return val
}

func readIntArray() []int {
	line := readLine()
	fields := strings.Fields(line)
	res := make([]int, len(fields))
	for i, f := range fields {
		res[i], _ = strconv.Atoi(f)
	}
	return res
}

func solution() {
	d := readIntArray()
	h1 := d[0]
	h2 := d[1]

	d = readIntArray()
	a := d[0]
	b := d[1]

	pos := h1 + 8*a
	dc := 0

	for {
		if pos >= h2 {
			fmt.Println(dc)
			return
		}

		if 12*a <= 12*b {
			fmt.Println(-1)
			return
		}

		pos -= 12 * b
		pos += 12 * a
		dc++
	}
}

func main() {
	solution()
}

